<script setup>
import { ref } from 'vue'
import { state,api,refresh,notify } from '../api'
import Icon from '../components/Icon.vue'
const name=ref(state.me.name),goal=ref(state.me.daily_goal),busy=ref(false),exporting=ref(false),error=ref('')
async function save(){busy.value=true;error.value='';try{state.me=await api('/me',{method:'PATCH',body:JSON.stringify({name:name.value,daily_goal:goal.value})});await refresh();notify('Đã lưu mục tiêu và hồ sơ của bạn')}catch(e){error.value=e.message}finally{busy.value=false}}
async function exportData(){exporting.value=true;try{const data=await api('/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`lingua-progress-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Đã xuất dữ liệu học của bạn')}catch(e){notify(e.message)}finally{exporting.value=false}}
</script>
<template><div class="page settings-page"><div class="page-heading"><div><div class="eyebrow">NHỊP HỌC CỦA RIÊNG BẠN</div><h1>Một mục tiêu vừa sức</h1><p>Chọn nhịp học bạn có thể duy trì mỗi ngày.</p></div></div><div class="settings-grid"><section class="settings-card"><h2>Hồ sơ & mục tiêu</h2><form @submit.prevent="save"><label>Tên của bạn<input v-model="name" required maxlength="40"/></label><label>Mục tiêu số từ mỗi ngày<select v-model.number="goal"><option v-for="n in [5,10,15,20,30,50,100]" :key="n" :value="n">{{n}} từ / ngày{{n===15 ? ' · Nhịp vừa phải' : ''}}</option></select></label><p class="muted">Mục tiêu tính theo số từ khác nhau bạn đã luyện trong ngày, kể cả flashcard và bài tập.</p><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="btn primary" :disabled="busy">{{busy ? 'Đang lưu…' : 'Lưu thay đổi'}}<Icon name="Check" :size="17"/></button></form></section><section class="settings-card"><span class="stat-icon green"><Icon name="Database"/></span><h2>Dữ liệu của bạn</h2><p>Tiến độ được lưu trên máy chủ ứng dụng. Trình duyệt này giữ mã hồ sơ để mở lại hành trình của bạn.</p><p>Xóa cookie hoặc đổi trình duyệt sẽ tạo hồ sơ mới. Bạn có thể xuất lịch sử học và từ tự thêm thành tệp JSON.</p><button class="btn outline" :disabled="exporting" @click="exportData"><Icon name="Download" :size="18"/>{{exporting ? 'Đang xuất…' : 'Xuất dữ liệu học'}}</button></section><section class="settings-card wide"><h2>Học thế nào cho dễ nhớ?</h2><div class="learning-tips"><div><span>01</span><h3>Học trong ngữ cảnh</h3><p>Đọc câu ví dụ, rồi đặt một câu đúng về cuộc sống của bạn.</p></div><div><span>02</span><h3>Tự nhớ trước khi xem</h3><p>Dừng vài giây ở mặt trước flashcard. Cố nhớ nghĩa rồi mới lật thẻ.</p></div><div><span>03</span><h3>Quay lại đều đặn</h3><p>Từ khó sẽ trở lại sớm hơn. Từ đã nhớ được giãn lịch ôn dần.</p></div></div><p class="small-note">Mức A1–B2 là nhãn gợi ý của bộ học, không phải kết quả đánh giá CEFR. Phát âm dùng giọng tiếng Anh có sẵn trên thiết bị; chất lượng và khả năng dùng ngoại tuyến tùy trình duyệt.</p></section></div></div></template>
